make('tong_ya','佟雅皇后',B,
'佟雅以富有寡妇的身份接洽外国财团，希望利用自己家族保留的北部土地开发矿产。她其实是本国皇后，出身旧日小王国的后裔，豪华宫殿、私人卫队和矿山是历史与制度赋予的资源，并非个人超能力。她谈吐优雅、英语流利，既有高贵的距离感，也能接受穆秀珍不拘礼节的友谊。迪逊和云三风相继死亡使她深受打击，她仍希望开发计划继续，不把受害者当作可以轻易替换的投资代表。她能从司机的神秘死亡推知木兰花夜间外出，但对山区恐惧的来源了解有限，一度相信贵族身份使自己免受降头，不能把这种信念当作实际免疫。身份被识破后，她请求以国家与私人两方面获得援助，把宫殿的人员和资源正式交木兰花调配，最明确的要求却是尽量爱护百姓。她的权力并不意味着可以随意消灭地方抵抗：村民对降头师的保护，使直接派兵难以奏效。最终调查揭出实权将军控制的犯罪组织，她在首都接受报告，案件促成主谋被捕和山区开发。终局仍是一位须依赖信息、专业人才和政治合作的统治者，善意与原有阶层观念同时保留。',
'恢复公开皇后身份推动桑达计划，邀请云氏技术人员合作开发北部。','政治授权与资源协调','通过法定地位、家产和人际信任调集人员，授权可信调查者行动。','身份不能免疫毒物，地方控制依赖民众合作；卫队与土地是情境资源，不能随身召出。',[(418,436,'外貌、教育与待客。'),(1040,1066,'根据线索推断外出。'),(1152,1194,'身份、家产、开发阻力。'),(1206,1236,'贵族免咒信念、授权与保护百姓。'),(1254,1268,'权力戒指的制度象征。'),(2358,2364,'逮捕与开发终局。')],
'将土地资源转为国家建设，又希望百姓不因权力冲突遭殃。',[('援助者遭到神秘袭击','缺少足够地方情报','忧惧而继续求助，并要求谨慎行动。'),('找到可信且有行动能力的人','自己的制度资源足够支持','给明确授权，同时提出保护百姓的底线。'),('事实揭出权势人物涉案','获得可核实证人与报告','动用正式权力推动调查和后续建设。')],scores=(0,1,1,2,1,3),tier='并',aliases=('佟雅夫人',),appearance='二十上下的修长少妇，乌黑长发与眼睛，举止高贵而带忧郁。')
make('sangda','桑达',B,
'桑达是皇后总管大臣的儿子，曾在英国读书，是几次勘察队与当地之间的联络者。他身材结实、态度亲切，最初习惯称木兰花为主人，得到朋友相待后才逐渐放松。他支持山区开发，认为教育、交通和矿产建设可以使国家富强；这种愿望来自实际工作，而不是全知的现代化口号。他亲手绘制简略却方向清楚的地图，知道野猪坡、勘察屋与矿区之间的关系，同时坦承自己多从直升机上观察，真正进入深山的经验有限。遭来福枪袭击时，他被碎玻璃划伤，才切身意识到所谓神秘山区也藏着现代武器。传统恐惧没有因留学就自动消失，飞行人头使他惊慌，他又能解释竹地板发声的警戒用途，将生活知识提供给同伴。看见机械人头被拆毁后，他有机会修正判断，却来不及完成自己的愿望。敌人麻醉并劫走巡逻者，把他当作必须除掉的本地参与人，随后用毒物杀害，还向木兰花展示其尸体以制造屈服。山区开发后来以桑达命名，肯定的是他的志向与代价，不意味着他获得了复活或守护土地的神性。参战恢复只允许最后可行动的青年形态保留这份经历。',
'在金庙被毒杀，后续开发工程以桑达计划纪念他。','地形记录与跨文化联络','凭既有勘察经历绘图、讲解路线，并为调查者解释本地生活与观念。','深山经验有限，对恐怖表象会害怕；无抗毒或超常武力证据。',[(1280,1322,'教育、形貌、联络与地图。'),(1382,1394,'遇袭受伤。'),(1742,1746,'解释竹地板。'),(1770,1814,'面对飞头的恐惧和思考。'),(2122,2136,'死亡与威慑。'),(2360,2362,'纪念工程。')],
'希望把所学用于家乡建设，也希望在朋友关系中承担实际责任。',[('有人需要本地路线','熟悉已有勘察范围','提供图示，坦承未知区域。'),('恐怖现象冲击既有认识','尚未得到解释','会害怕，但愿随同伴观察证据。'),('建设计划受到阻碍','还有可做的具体工作','继续承担联络与向导责任。')],scores=(1,0,0,1,1,1),tier='纸',dead=True)
make('meisi','梅斯',B,
'梅斯以总降头师主要助手的身份出现，真身是实权将军的上校参谋长，早年又做过药剂师。他把药物知识、组织纪律与神秘表演结合，用昏迷、延迟毒发和解药控制迫使外来者退出山区。面对木兰花，他先摆出礼貌和和平的姿态，声称组织只是守护一片不受打扰的乐土；随即以被掳同伴与针孔威胁她，显示所谓保护只是犯罪利益的说辞。他很注意皇后戒指代表的政治后果，不愿在会立即招来军队搜索的时机杀人，却准备让调查者回家后发病，使死亡继续为降头传说背书。他熟悉毒物，却没有同等程度的近身防御，离开总部后被木兰花和穆秀珍制住。对手把危险反施其身，他立刻从傲慢变成恐惧，急着调取解药救命，又企图以高级职位诱使她们合作。他透露首领的将军身份和财富优势，反而使木兰花决定将他作为重要证人带走。最终解药救了双方，他被麻醉后押往首都，作为参谋长随主谋被捕。其能力依赖具体药物、施用机会和组织支持，不能把本文的虚构毒理扩张为任意控制生死。',
'被带回首都，真实上校参谋长身份揭露，与主谋一同遭逮捕。','药物控制与组织谈判','使用剧情中的麻醉、毒物及对应解药制造延迟威胁，配合人员和伪装施压。','需要药物接触与物资；本人同样会中毒，近身失势时容易因求生泄露组织信息。',[(1980,2040,'身份伪装、和平话术与毒物威胁。'),(2190,2250,'被制服、反中毒与药剂师自述。'),(2254,2304,'取解药、招揽及将军线索。'),(2318,2324,'解毒后被麻醉。'),(2358,2358,'真实军职与逮捕。')],
'维护将军集团的秘密与收益，在自认绝对掌控时显示优越，一旦自身危险则优先求生。',[('外来者接近秘密','组织能控制接触和药物','用神秘威慑包装强制驱逐。'),('对方没有立刻屈服','同伴和解药仍在手中','加码时间压力，自信地解释部分机制。'),('自己也陷入同等危险','对方掌握行动主动','急于合作求救，可能透露原本守口的秘密。')],roles=('反派',),scores=(2,0,1,3,2,2),tier='并')
make('gold_temple_general','金庙总降头师／实权将军',B,
'金庙的总降头师以涂金面具遮脸，在山崖中的现代化总部接见来客，让外观狰狞的神像与自动机关共同制造超自然权威。他的真实姓名未公布，终局确认是一位拥有实权的将军，梅斯是他的上校参谋长；不可凭匿名军职将他拼接成别书人物。他利用分布各村的降头师网络、精巧飞头机械和毒物把持山区，使村民既保护组织又恐惧调查。他杀害踏入金庙并挑战其权威的迪逊与云三风，后来又杀死本地向导桑达，在电视上向木兰花展示尸体，试图使她相信顺从才能生还。对外来名人，他反而安排延迟死亡，以免立刻引来皇后的追查，并让离开后的死亡继续巩固降头传说。逃出山谷时发现的大片罂粟及终局调查，揭出组织以迷信保护非法财富的实际背景；更高政治地位的野心由梅斯暗示，并非已完成篡位。他最终因证人被带回首都而免职逮捕，不能把旧有军职当作拘押后仍可自由调用的常驻军队。其威慑有社会基础和物质装置，面具之下仍是会误判对手的普通人。',
'犯罪被揭露后三天内遭免职和逮捕，旧组织控制被打破。','秘密网络与恐惧统治','借分散的降头师、现代机关、毒物和军政背景构造不敢调查的禁区。','依赖组织、基地和民众信息隔离；无真实降头或神性，被揭露后政治资源可撤销。',[(1174,1188,'组织与地方恐惧。'),(2100,2146,'面具、控制机关、杀桑达与延期死亡策略。'),(2166,2170,'承认处置云三风和迪逊。'),(2276,2304,'将军身份及更高职位暗示。'),(2342,2360,'罂粟发现与逮捕终局。')],
'阻止外部开发破坏非法控制和财富来源，以神秘权威维持地方支配。',[('有人挑战被塑造的神威','能够隐蔽接近或下毒','惩罚挑战者，使死亡强化恐惧。'),('对手有重要政治关系','立即失踪会引起搜索','选择延迟威胁和驱逐，避免眼前曝光。'),('部下暴露可核实证据','身份与组织被连在一起','优先控制证人与消息，但制度保护可能崩溃。')],roles=('反派',),scores=(2,1,2,3,2,3),tier='并',uncertainties=['未提供真名；更高政治野心来自梅斯暗示，未发生实际篡位。'])
make('gold_temple_village_shaman','金庙组织的村落降头师',B,
'这名村落降头师没有公布姓名，是木兰花一行进入山区时直接接触的组织成员。他以当地宗教习俗和死亡禁忌约束来客，收留众人时警告不要触碰屋内动物，也不准夜里走出房间。被追问迪逊与金庙的关系，他不作解释，只用迪逊已经死去的事实压住话题；这种回答让恐惧代替证据。他声称自己只是因游客学过几句英语，实际能与梅斯配合控制村民、关门隔绝谈话，并在众人被麻醉劫持之后继续参与押送。木兰花面对他的地方语言与神秘说法，不能简单依靠主角声望获得真相。他后来驾驶装有履带的山地车辆，把木兰花送往隐藏的金庙总部，显示其角色是组织交通与拘禁的一环，而非脱离物质条件施法的巫师。村内的麻醉行动和飞头装置属于整个网络，正文没有逐一确认每个开关或针筒都是由他亲手操作，因此个人卡只保留已经出现的接待、威胁、指挥与押运行为。主谋落网后，没有单独交代他的审判或死亡；综合卡保持最后实际行动形态，并将继续调动总部资源列为条件，而不默认为原组织仍完好。',
'最后确认行动是协助梅斯押送调查者到金庙；组织后被揭露，个人处置未另述。','地方威慑与山地押运','借村落身份维持纪律和恐惧，驾驶专用车辆连接隐蔽基地。','依赖地方信仰、同伙与车辆；没有真实巫术，也未证实单独掌握整个毒物机械系统。',[(1700,1732,'禁令、语言与死亡威慑。'),(1964,1980,'与梅斯共同出场并驱散村民。'),(2052,2062,'押送和履带车。')],
'维护地方组织的秘密与命令，使外来者按照既定规则行动。',[('来客触碰组织物品','能利用禁忌建立权威','用死亡警告制止接近。'),('被问及核心基地','对方尚缺事实','以已死前人的遭遇封住追问。'),('上级安排转移人员','车和路线可用','服从押运并避免向外透露总部位置。')],roles=('反派',),scores=(1,0,1,2,1,1),tier='并')
make('dixon','迪逊',B,
'迪逊是美国工程师，带领地质人员在皇后北部土地进行矿产勘察。他是投资计划中把科学调查转为可用报告的关键人物，与云三风共同进入山区，留下足以让云氏判断合作前景的成果。他在当地人缘良好，皇后认为这可能使他找到普通人不知的金庙；主谋后来确认，两人实际花钱买通一名手下才进入，并未见到隐藏总部，只见庙堂神像。受科学教育的迪逊不相信降头，曾与云三风直接挑战总降头师，宣告开发将带来文明。事实最终证明所谓法术背后有毒物与机械，但他的正确怀疑没有自动变成安全策略，也没有使身体免受暗害。他被送进医院后逐渐死亡，临终向童医生断续讲述入庙经过，并承认对方已经做到了杀人的威胁。他的死因与云三风、后来的被害者连在一起，使木兰花有了追索组织的线索。角色不能只剩无辜尸体，也不能被塑造成看穿全部阴谋的先知：他有专业知识和勇于质疑的性格，同时轻估了掌握地方资源者会怎样报复。最后可行动形态应保留工程与考察能力，不恢复死亡时已经失去的安全保障，更不给临终经历附加通灵能力。',
'在医院因组织毒物死亡，留下口述线索；其勘察成果后来用于开发。','地质勘察与工程评估','带队考察矿藏，整理报告并与投资方协作。','专业判断不等于反暗杀能力；不熟悉对方隐蔽手段，挑战权威可能暴露自身。',[(246,266,'投资背景与共同勘察。'),(438,480,'报告、死亡和医院。'),(672,684,'临终口述。'),(1180,1188,'当地人缘和考察信息。'),(2166,2166,'买通入庙与主谋承认。'),(2358,2362,'技术开发延续。')],
'用考察与科学知识推进工程，不愿向未经证实的神秘权威屈服。',[('需要判断开发价值','能够开展实地勘察','组织专业人员形成可讨论报告。'),('地方禁忌阻止调查','确信缺乏科学根据','主动求证甚至挑战，但可能轻估人的恶意。'),('危险已经发生','还有清醒表达机会','说出关键经历，为后来者留下线索。')],scores=(0,0,0,1,1,2),tier='纸',dead=True)
